import 'package:flutter/material.dart';

import '../../../data/models.dart';
import 'overlay_text_element.dart';
import 'text_overlay_utils.dart';

class OverlayTextLayer extends StatelessWidget {
  final TextOverlayConfig overlay;
  final Size imageSize;
  final int activeWordIndex;
  final bool isActive;
  final void Function(String word, int globalIndex)? onWordTap;

  const OverlayTextLayer({
    super.key,
    required this.overlay,
    required this.imageSize,
    required this.activeWordIndex,
    required this.isActive,
    this.onWordTap,
  });

  @override
  Widget build(BuildContext context) {
    if (imageSize.width <= 0 || imageSize.height <= 0) {
      return const SizedBox.shrink();
    }

    final wordStarts = calculateWordStartsByElementId(overlay);

    return Stack(
      clipBehavior: Clip.none,
      children: [
        for (var i = 0; i < overlay.elements.length; i++)
          OverlayTextElement(
            element: overlay.elements[i],
            elementIndex: i,
            imageSize: imageSize,
            wordStartIndex: wordStarts[overlay.elements[i].id] ?? 0,
            activeWordIndex: activeWordIndex,
            isActive: isActive,
            onWordTap: onWordTap,
          ),
      ],
    );
  }
}

import React, { useMemo } from 'react';
import { View } from 'react-native';
import type { TextOverlayConfig } from '@/types';
import { calculateWordStartsByElementId } from '@/lib/textOverlay';
import { OverlayTextElement } from './OverlayTextElement';

interface OverlayTextLayerProps {
  overlay: TextOverlayConfig;
  imageWidth: number;
  imageHeight: number;
  activeWordIndex?: number;
  pronouncingWordIndex?: number | null;
  isActive: boolean;
  onWordTap?: (word: string, globalIndex: number) => void;
}

export function OverlayTextLayer({
  overlay,
  imageWidth,
  imageHeight,
  activeWordIndex,
  pronouncingWordIndex,
  isActive,
  onWordTap,
}: OverlayTextLayerProps) {
  // Compute global word start indices for each element
  const wordStartsByElementId = useMemo(() => {
    return calculateWordStartsByElementId(overlay);
  }, [overlay]);

  // Return null if dimensions are invalid
  if (imageWidth === 0 || imageHeight === 0) {
    return null;
  }

  return (
    <View
      style={{
        position: 'absolute',
        top: 0,
        left: 0,
        width: imageWidth,
        height: imageHeight,
      }}
      pointerEvents="box-none"
    >
      {overlay.elements.map((element, index) => (
        <OverlayTextElement
          key={element.id}
          element={element}
          elementIndex={index}
          imageWidth={imageWidth}
          imageHeight={imageHeight}
          wordStartIndex={wordStartsByElementId.get(element.id) ?? 0}
          activeWordIndex={activeWordIndex}
          pronouncingWordIndex={pronouncingWordIndex}
          isActive={isActive}
          onWordTap={onWordTap}
        />
      ))}
    </View>
  );
}

import 'package:flutter/material.dart';
import 'package:flutter_animate/flutter_animate.dart';

import '../../../data/models.dart';
import 'text_overlay_utils.dart';

class OverlayTextElement extends StatelessWidget {
  final TextElement element;
  final int elementIndex;
  final Size imageSize;
  final int wordStartIndex;
  final int activeWordIndex;
  final bool isActive;
  final void Function(String word, int globalIndex)? onWordTap;

  const OverlayTextElement({
    super.key,
    required this.element,
    required this.elementIndex,
    required this.imageSize,
    required this.wordStartIndex,
    required this.activeWordIndex,
    required this.isActive,
    this.onWordTap,
  });

  @override
  Widget build(BuildContext context) {
    final left = (element.x / 100) * imageSize.width;
    final top = (element.y / 100) * imageSize.height;
    final width = (element.width / 100) * imageSize.width;
    final fontSize = (element.fontSize / 100) * imageSize.height;

    final baseStyle =
        resolveFontStyle(
          element.fontFamily,
          element.fontWeight,
          fontSize,
          parseHexColor(element.color),
        ).copyWith(
          height: 1.3,
          shadows: element.shadow == null
              ? null
              : [
                  Shadow(
                    color: parseHexColor(
                      element.shadow!.color,
                      fallback: Colors.black,
                    ),
                    offset: Offset(element.shadow!.x, element.shadow!.y),
                    blurRadius: element.shadow!.blur,
                  ),
                ],
        );

    final background = element.background;

    Widget content = RichText(
      textAlign: resolveTextAlign(element.textAlign),
      text: TextSpan(style: baseStyle, children: _buildSpans(baseStyle)),
    );

    if (background != null) {
      content = Container(
        padding: EdgeInsets.all(background.padding ?? 0),
        decoration: BoxDecoration(
          color: parseHexColor(background.color, fallback: Colors.transparent),
          borderRadius: BorderRadius.circular(background.borderRadius ?? 0),
        ),
        child: content,
      );
    }

    final rotated = element.rotation != 0
        ? Transform.rotate(
            angle: (element.rotation * 3.141592653589793) / 180,
            child: content,
          )
        : content;

    return Positioned(
      left: left,
      top: top,
      width: width,
      child: rotated
          .animate(target: isActive ? 1 : 0)
          .fadeIn(
            duration: 350.ms,
            delay: Duration(milliseconds: 180 + elementIndex * 40),
          )
          .slideY(
            begin: 0.12,
            end: 0,
            duration: 350.ms,
            delay: Duration(milliseconds: 180 + elementIndex * 40),
          ),
    );
  }

  List<InlineSpan> _buildSpans(TextStyle baseStyle) {
    final tokens = RegExp(
      r'\s+|\S+',
    ).allMatches(element.text).map((m) => m.group(0) ?? '').toList();
    final spans = <InlineSpan>[];
    var currentWordIndex = wordStartIndex;

    for (final token in tokens) {
      if (token.trim().isEmpty) {
        spans.add(TextSpan(text: token, style: baseStyle));
        continue;
      }

      final globalIndex = currentWordIndex;
      currentWordIndex += 1;
      final isHighlighted = globalIndex == activeWordIndex;

      final wordText = Text(
        token,
        style: isHighlighted
            ? baseStyle.copyWith(
                backgroundColor: const Color.fromRGBO(212, 237, 188, 0.8),
                fontWeight: FontWeight.w700,
              )
            : baseStyle,
      );

      if (onWordTap == null) {
        spans.add(
          WidgetSpan(
            child: wordText,
            alignment: PlaceholderAlignment.baseline,
            baseline: TextBaseline.alphabetic,
          ),
        );
        continue;
      }

      spans.add(
        WidgetSpan(
          alignment: PlaceholderAlignment.baseline,
          baseline: TextBaseline.alphabetic,
          child: GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: () => onWordTap?.call(token, globalIndex),
            child: wordText,
          ),
        ),
      );
    }

    return spans;
  }
}

import React, { useEffect } from 'react';
import { Text, View, StyleSheet, Pressable, type TextStyle, type ViewStyle } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withTiming,
  withDelay,
  Easing,
} from 'react-native-reanimated';
import type { TextElement } from '@/types';
import { resolveFont } from '@/lib/textOverlay';

interface OverlayTextElementProps {
  element: TextElement;
  elementIndex: number;
  imageWidth: number;
  imageHeight: number;
  wordStartIndex: number;
  activeWordIndex?: number;
  pronouncingWordIndex?: number | null;
  isActive: boolean;
  onWordTap?: (word: string, globalIndex: number) => void;
}

export function OverlayTextElement({
  element,
  elementIndex,
  imageWidth,
  imageHeight,
  wordStartIndex,
  activeWordIndex,
  pronouncingWordIndex,
  isActive,
  onWordTap,
}: OverlayTextElementProps) {
  // Animation value
  const progress = useSharedValue(0);

  // Stagger entrance animation
  useEffect(() => {
    if (isActive) {
      const delay = 180 + elementIndex * 40;
      progress.value = withDelay(
        delay,
        withTiming(1, {
          duration: 350,
          easing: Easing.out(Easing.ease),
        })
      );
    } else {
      // Reset immediately when inactive
      progress.value = 0;
    }
  }, [isActive, elementIndex, progress]);

  // Animated style for container
  const animatedStyle = useAnimatedStyle(() => ({
    opacity: progress.value,
    transform: [{ translateY: (1 - progress.value) * 16 }],
  }));

  // Convert percentage to pixels
  const x = (element.x / 100) * imageWidth;
  const y = (element.y / 100) * imageHeight;
  const width = (element.width / 100) * imageWidth;

  // Resolve font family (weight encoded in name)
  const fontFamily = resolveFont(element.fontFamily, element.fontWeight);

  // Calculate font size based on image height (assuming 100% = full image height)
  const fontSize = (element.fontSize / 100) * imageHeight;

  // Build text style
  const textStyle: TextStyle = {
    fontFamily,
    fontSize,
    color: element.color,
    textAlign: element.textAlign,
    lineHeight: fontSize * 1.3,
  };

  // Shadow style
  const shadowStyle: TextStyle = element.shadow
    ? {
        textShadowColor: element.shadow.color,
        textShadowOffset: { width: element.shadow.x, height: element.shadow.y },
        textShadowRadius: element.shadow.blur,
      }
    : {};

  // Container styles
  const containerStyle: ViewStyle = {
    position: 'absolute',
    left: x,
    top: y,
    width,
    transform: element.rotation !== 0 ? [{ rotate: `${element.rotation}deg` }] : undefined,
  };

  // Background container style
  const backgroundStyle: ViewStyle = element.background
    ? {
        backgroundColor: element.background.color,
        padding: element.background.padding || 0,
        borderRadius: element.background.borderRadius || 0,
      }
    : {};

  // Split text into tokens (preserving whitespace)
  const tokens = element.text.split(/(\s+)/);

  // Check if a word is highlighted
  const isWordHighlighted = (globalIndex: number): boolean => {
    if (activeWordIndex !== undefined && globalIndex === activeWordIndex) {
      return true;
    }
    if (pronouncingWordIndex !== null && pronouncingWordIndex !== undefined && globalIndex === pronouncingWordIndex) {
      return true;
    }
    return false;
  };

  // Word index tracker
  let currentWordIndex = wordStartIndex;

  return (
    <Animated.View style={[containerStyle, animatedStyle]} pointerEvents="box-none">
      <View style={backgroundStyle}>
        <Text style={[textStyle, shadowStyle]}>
          {tokens.map((token, tokenIndex) => {
            // Check if token is whitespace
            if (/^\s+$/.test(token)) {
              return token;
            }

            // It's a word
            const globalIndex = currentWordIndex;
            const isHighlighted = isWordHighlighted(globalIndex);
            currentWordIndex++;

            const wordStyle: TextStyle = isHighlighted
              ? {
                  backgroundColor: 'rgba(212, 237, 188, 0.8)',
                  borderRadius: 4,
                  paddingHorizontal: 2,
                }
              : {};

            if (onWordTap) {
              return (
                <Pressable
                  key={tokenIndex}
                  onPress={() => onWordTap(token, globalIndex)}
                  style={styles.pressableWord}
                >
                  <Text style={[textStyle, shadowStyle, wordStyle]}>{token}</Text>
                </Pressable>
              );
            }

            return (
              <Text key={tokenIndex} style={[textStyle, shadowStyle, wordStyle]}>
                {token}
              </Text>
            );
          })}
        </Text>
      </View>
    </Animated.View>
  );
}

const styles = StyleSheet.create({
  pressableWord: {
    display: 'flex',
  },
});

import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';

