import 'dart:async';

import 'package:audio_session/audio_session.dart';
import 'package:just_audio/just_audio.dart';

import '../data/models.dart';

class AudioEngine {
  final AudioPlayer _narration = AudioPlayer();
  final AudioPlayer _soundscape = AudioPlayer();

  bool _initialized = false;
  Timer? _crossfadeTimer;
  String? _currentSoundscapeUrl;

  Future<void> ensureInitialized() async {
    if (_initialized) {
      return;
    }

    final session = await AudioSession.instance;
    await session.configure(const AudioSessionConfiguration.music());

    _soundscape.setLoopMode(LoopMode.one);
    await _soundscape.setVolume(0.6);

    _initialized = true;
  }

  Future<void> loadPage(PageData page) async {
    await ensureInitialized();

    final futures = <Future<void>>[];

    if (page.narrationUrl != null && page.narrationUrl!.isNotEmpty) {
      futures.add(_narration.setUrl(page.narrationUrl!).then((_) {}));
    } else {
      futures.add(_narration.stop());
    }

    if (page.soundscapeUrl != null && page.soundscapeUrl!.isNotEmpty) {
      futures.add(_soundscape.setUrl(page.soundscapeUrl!).then((_) {}));
      _currentSoundscapeUrl = page.soundscapeUrl;
    } else {
      futures.add(_soundscape.stop());
      _currentSoundscapeUrl = null;
    }

    await Future.wait(futures);
  }

  Future<void> play() async {
    await ensureInitialized();
    await Future.wait([_narration.play(), _soundscape.play()]);
  }

  Future<void> pause() async {
    await Future.wait([_narration.pause(), _soundscape.pause()]);
  }

  Future<void> transitionToPage(PageData nextPage) async {
    await ensureInitialized();

    final nextSoundscapeUrl = nextPage.soundscapeUrl;

    if (nextSoundscapeUrl == null || nextSoundscapeUrl.isEmpty) {
      await _soundscape.stop();
      await _narration.stop();
      _currentSoundscapeUrl = null;
      return;
    }

    if (_currentSoundscapeUrl == nextSoundscapeUrl) {
      if (nextPage.narrationUrl != null && nextPage.narrationUrl!.isNotEmpty) {
        await _narration.setUrl(nextPage.narrationUrl!);
        await _narration.play();
      }
      return;
    }

    _crossfadeTimer?.cancel();
    await _soundscape.setVolume(0);
    await loadPage(nextPage);
    await _soundscape.play();
    await _narration.play();

    const steps = 15;
    const duration = Duration(milliseconds: 1500);
    const targetVolume = 0.6;
    final tick = duration ~/ steps;
    var currentStep = 0;

    _crossfadeTimer = Timer.periodic(tick, (timer) async {
      currentStep += 1;
      final progress = currentStep / steps;
      await _soundscape.setVolume(targetVolume * progress);
      if (currentStep >= steps) {
        timer.cancel();
      }
    });

import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter_animate/flutter_animate.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:google_fonts/google_fonts.dart';

import '../../audio/audio_providers.dart';
import '../../data/models.dart';
import '../../data/providers.dart';
import 'page_renderer.dart';

class ReaderScreen extends ConsumerStatefulWidget {
  final String bookId;

  const ReaderScreen({super.key, required this.bookId});

  @override
  ConsumerState<ReaderScreen> createState() => _ReaderScreenState();
}

class _ReaderScreenState extends ConsumerState<ReaderScreen> {
  final PageController _pageController = PageController();
  final ValueNotifier<Duration> _narrationPositionNotifier = ValueNotifier(
    Duration.zero,
  );
  int _activePageIndex = 0;
  bool _isPlaying = false;
  bool _showChrome = true;
  bool _loadedInitialAudio = false;
  double _narrationVolume = 1;
  double _soundscapeVolume = 0.6;
  StreamSubscription<Duration>? _positionSubscription;
  StreamSubscription<bool>? _playingSubscription;

  @override
  void initState() {
    super.initState();
    final audioEngine = ref.read(audioEngineProvider);
    audioEngine.ensureInitialized();

    _positionSubscription = audioEngine.narrationPosition.listen((position) {
      if (!mounted) {
        return;
      }
      _narrationPositionNotifier.value = position;
    });

    _playingSubscription = audioEngine.narrationPlaying.listen((playing) {
      if (!mounted) {
        return;
      }
      setState(() {
        _isPlaying = playing;
      });
    });
  }

  @override
  void dispose() {
    _positionSubscription?.cancel();
    _playingSubscription?.cancel();
    _narrationPositionNotifier.dispose();
    _pageController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final bookAsync = ref.watch(currentBookProvider(widget.bookId));
    final audioEngine = ref.watch(audioEngineProvider);

    return Scaffold(
      backgroundColor: const Color(0xFF121A24),
      body: bookAsync.when(
        data: (book) {
          if (book == null) {
            return const Center(child: Text('Book not found'));
          }

          if (book.pages.isEmpty) {
            return const Center(child: Text('No pages in this book'));
          }

          if (_activePageIndex >= book.pages.length) {
            _activePageIndex = book.pages.length - 1;
          }

          final activePage = book.pages[_activePageIndex];

          if (!_loadedInitialAudio) {
            _loadedInitialAudio = true;
            WidgetsBinding.instance.addPostFrameCallback((_) async {
              await audioEngine.loadPage(book.pages[_activePageIndex]);
            });
          }

          return Stack(
            children: [
              GestureDetector(
                behavior: HitTestBehavior.translucent,
                onTap: () => setState(() => _showChrome = !_showChrome),
                child: PageView.builder(
                  controller: _pageController,
                  reverse: true,
                  itemCount: book.pages.length,
                  onPageChanged: (index) async {
                    setState(() {
                      _activePageIndex = index;
                    });
                    await audioEngine.transitionToPage(book.pages[index]);
                  },
                  itemBuilder: (context, index) {
                    final isInVirtualizationWindow =
                        (index - _activePageIndex).abs() <= 1;
                    if (!isInVirtualizationWindow) {
                      return const SizedBox.shrink();
                    }
                    final page = book.pages[index];
                    return ValueListenableBuilder<Duration>(
                      valueListenable: _narrationPositionNotifier,
                      builder: (context, narrationPosition, child) {
                        return PageRenderer(
                          page: page,
                          narrationPosition: narrationPosition,
                          isActive: index == _activePageIndex,
                        );
                      },
                    );
                  },
                ),
              ),
              IgnorePointer(
                ignoring: !_showChrome,
                child: AnimatedOpacity(
                  opacity: _showChrome ? 1 : 0,
                  duration: 220.ms,
                  curve: Curves.easeOut,
                  child: _ReaderChrome(
                    book: book,
                    activePageIndex: _activePageIndex,
                    activePageNumber: activePage.pageNumber,
                    isPlaying: _isPlaying,
                    onClose: () => Navigator.of(context).maybePop(),
                    onPlayPause: () async {
                      if (_isPlaying) {
                        await audioEngine.pause();
                      } else {
                        await audioEngine.play();
                      }
                    },
                    onAudioSettingsTap: () =>
                        _showAudioSettings(context, audioEngine),
                  ),
                ),
              ),
            ],
          );
        },
        loading: () => const _ReaderLoadingState(),
        error: (error, _) => _ReaderErrorState(error: '$error'),
      ),
    );
  }

  Future<void> _showAudioSettings(BuildContext context, dynamic audioEngine) {
    return showModalBottomSheet<void>(
      context: context,
      backgroundColor: const Color(0xFFF9F8F4),
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
      ),
      builder: (context) {
        return StatefulBuilder(
          builder: (context, setModalState) {
            return Padding(
              padding: const EdgeInsets.fromLTRB(18, 18, 18, 28),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Center(
                    child: Container(
                      width: 46,
                      height: 5,
                      decoration: BoxDecoration(
                        color: const Color(0xFFD7D7D2),
                        borderRadius: BorderRadius.circular(999),
                      ),
                    ),
                  ),
                  const SizedBox(height: 16),
                  Text(
                    'Audio Mix',
                    style: GoogleFonts.playfairDisplay(
                      fontSize: 26,
                      fontWeight: FontWeight.w700,
                      color: const Color(0xFF2E2A3D),
                    ),
                  ),
                  const SizedBox(height: 18),
                  _VolumeRow(
                    icon: Icons.record_voice_over_rounded,
                    label: 'Narration',
                    value: _narrationVolume,
                    onChanged: (value) async {
                      setModalState(() => _narrationVolume = value);
                      setState(() => _narrationVolume = value);
                      await audioEngine.setNarrationVolume(value);
                    },
                  ),
                  const SizedBox(height: 14),
                  _VolumeRow(
                    icon: Icons.surround_sound_rounded,
                    label: 'Ambience',
                    value: _soundscapeVolume,
                    onChanged: (value) async {
                      setModalState(() => _soundscapeVolume = value);
                      setState(() => _soundscapeVolume = value);
                      await audioEngine.setSoundscapeVolume(value);
                    },
                  ),
                ],
              ),
            );
          },
        );
      },
    );
  }
}

