import 'package:flutter/material.dart';
import 'package:flutter_animate/flutter_animate.dart';

import '../../../data/models.dart';
import 'text_overlay_utils.dart';

class OverlayTextElement extends StatelessWidget {
  final TextElement element;
  final int elementIndex;
  final Size imageSize;
  final int wordStartIndex;
  final int activeWordIndex;
  final bool isActive;
  final void Function(String word, int globalIndex)? onWordTap;

  const OverlayTextElement({
    super.key,
    required this.element,
    required this.elementIndex,
    required this.imageSize,
    required this.wordStartIndex,
    required this.activeWordIndex,
    required this.isActive,
    this.onWordTap,
  });

  @override
  Widget build(BuildContext context) {
    final left = (element.x / 100) * imageSize.width;
    final top = (element.y / 100) * imageSize.height;
    final width = (element.width / 100) * imageSize.width;
    final fontSize = (element.fontSize / 100) * imageSize.height;

    final baseStyle =
        resolveFontStyle(
          element.fontFamily,
          element.fontWeight,
          fontSize,
          parseHexColor(element.color),
        ).copyWith(
          height: 1.3,
          shadows: element.shadow == null
              ? null
              : [
                  Shadow(
                    color: parseHexColor(
                      element.shadow!.color,
                      fallback: Colors.black,
                    ),
                    offset: Offset(element.shadow!.x, element.shadow!.y),
                    blurRadius: element.shadow!.blur,
                  ),
                ],
        );

    final background = element.background;

    Widget content = RichText(
      textAlign: resolveTextAlign(element.textAlign),
      text: TextSpan(style: baseStyle, children: _buildSpans(baseStyle)),
    );

    if (background != null) {
      content = Container(
        padding: EdgeInsets.all(background.padding ?? 0),
        decoration: BoxDecoration(
          color: parseHexColor(background.color, fallback: Colors.transparent),
          borderRadius: BorderRadius.circular(background.borderRadius ?? 0),
        ),
        child: content,
      );
    }

    final rotated = element.rotation != 0
        ? Transform.rotate(
            angle: (element.rotation * 3.141592653589793) / 180,
            child: content,
          )
        : content;

    return Positioned(
      left: left,
      top: top,
      width: width,
      child: rotated
          .animate(target: isActive ? 1 : 0)
          .fadeIn(
            duration: 350.ms,
            delay: Duration(milliseconds: 180 + elementIndex * 40),
          )
          .slideY(
            begin: 0.12,
            end: 0,
            duration: 350.ms,
            delay: Duration(milliseconds: 180 + elementIndex * 40),
          ),
    );
  }

  List<InlineSpan> _buildSpans(TextStyle baseStyle) {
    final tokens = RegExp(
      r'\s+|\S+',
    ).allMatches(element.text).map((m) => m.group(0) ?? '').toList();
    final spans = <InlineSpan>[];
    var currentWordIndex = wordStartIndex;

    for (final token in tokens) {
      if (token.trim().isEmpty) {
        spans.add(TextSpan(text: token, style: baseStyle));
        continue;
      }

      final globalIndex = currentWordIndex;
      currentWordIndex += 1;
      final isHighlighted = globalIndex == activeWordIndex;

      final wordText = Text(
        token,
        style: isHighlighted
            ? baseStyle.copyWith(
                backgroundColor: const Color.fromRGBO(212, 237, 188, 0.8),
                fontWeight: FontWeight.w700,
              )
            : baseStyle,
      );

      if (onWordTap == null) {
        spans.add(
          WidgetSpan(
            child: wordText,
            alignment: PlaceholderAlignment.baseline,
            baseline: TextBaseline.alphabetic,
          ),
        );
        continue;
      }

      spans.add(
        WidgetSpan(
          alignment: PlaceholderAlignment.baseline,
          baseline: TextBaseline.alphabetic,
          child: GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: () => onWordTap?.call(token, globalIndex),
            child: wordText,
          ),
        ),
      );
    }

    return spans;
  }
}

import { useCallback } from 'react';
import { Dimensions } from 'react-native';
import { useAnimatedStyle, SharedValue } from 'react-native-reanimated';

const { height: SCREEN_HEIGHT } = Dimensions.get('window');

/**
 * Continuous scrollOffset architecture:
 *
 * scrollOffset is a single SharedValue representing the total vertical scroll position.
 * At rest on page N, scrollOffset = -N * SCREEN_HEIGHT.
 *
 * Each page's position is derived from:
 *   pageTranslateY = scrollOffset + pageIndex * SCREEN_HEIGHT
 *
 * All easing, momentum (withDecay), and snap behaviour live in the gesture
 * handler that drives scrollOffset — the styles here are pure position math.
 */
export function usePageAnimatedStyle(
  scrollOffset: SharedValue<number>,
  activeIndexShared: SharedValue<number>
): (pageIndex: number) => ReturnType<typeof useAnimatedStyle> {
  return useCallback(
    (pageIndex: number) => {
      return useAnimatedStyle(() => {
        const activeIndex = activeIndexShared.value;
        const diff = pageIndex - activeIndex;

        // Base position derived from continuous scroll offset
        const baseY = scrollOffset.value + pageIndex * SCREEN_HEIGHT;

        // ── Active page (diff === 0) ──────────────────────────────
        // Tracks scrollOffset directly — no extra transform needed.
        if (diff === 0) {
          return {
            transform: [{ translateY: baseY }],
            opacity: 1,
            zIndex: 2,
          };
        }

        // ── Next page (diff === 1) ────────────────────────────────
        // Sits at SCREEN_HEIGHT below when at rest, slides up as
        // scrollOffset decreases. No per-style easing — smoothness
        // comes from the scrollOffset animation itself.
        if (diff === 1) {
          return {
            transform: [{ translateY: baseY }],
            opacity: 1,
            zIndex: 3,
          };
        }

        // ── Previous page (diff === -1) ───────────────────────────
        // Parallax: moves at 70% speed when above viewport, creating
        // a sense of depth — the previous page lags behind slightly.
        // Opacity fades to 0.25 as it moves fully above.
        if (diff === -1) {
          const parallaxY = baseY < 0 ? baseY * 0.7 : baseY;

          // progress: 0 when page is at rest (baseY = 0), 1 when fully above
          const progress = Math.min(Math.max(-baseY / SCREEN_HEIGHT, 0), 1);
          const opacity = 1 - progress * 0.75; // fades from 1.0 → 0.25

          return {
            transform: [{ translateY: parallaxY }],
            opacity,
            zIndex: 1,
          };
        }

        // ── Off-screen pages (|diff| > 1) ─────────────────────────
        // Hidden and positioned out of view to avoid unnecessary rendering.
        return {
          transform: [{ translateY: diff > 0 ? SCREEN_HEIGHT : -SCREEN_HEIGHT }],
          opacity: 0,
          zIndex: 0,
        };
      });
    },
    [scrollOffset, activeIndexShared]
  );
}

